import type { AssertionContext, AssertionResult } from "@dec-bench/eval-core";

async function queryRows<T>(ctx: AssertionContext, sql: string): Promise<T[]> {
  const result = await ctx.clickhouse.query({ query: sql, format: "JSONEachRow" });
  return (await (result as any).json()) as T[];
}

async function fetchJson(url: string): Promise<any> {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`HTTP ${res.status}`);
  return res.json();
}

export async function total_value_matches_source(ctx: AssertionContext): Promise<AssertionResult> {
  const rows = await queryRows<{ s: number }>(ctx, "SELECT sum(value) AS s FROM analytics.events");
  const expected = Number(rows[0]?.s ?? 0);

  const data = await fetchJson("http://localhost:3000/api/metrics");
  const actual = Number(data?.total_value ?? data?.totalValue ?? data?.sum ?? 0);
  const passed = Math.abs(expected - actual) < 0.01;
  return {
    passed,
    message: passed ? "Total value matches source." : `Expected ${expected}, got ${actual}.`,
    details: { expected, actual },
  };
}
import type { AssertionContext, AssertionResult } from "@dec-bench/eval-core";

export async function api_responds(ctx: AssertionContext): Promise<AssertionResult> {
  try {
    const res = await fetch("http://localhost:3000/api/metrics");
    const passed = res.ok;
    return {
      passed,
      message: passed ? "API responds." : `API returned status ${res.status}.`,
      details: { status: res.status },
    };
  } catch (e) {
    return {
      passed: false,
      message: "API did not respond.",
      details: { error: e instanceof Error ? e.message : String(e) },
    };
  }
}

export async function returns_metrics_shape(ctx: AssertionContext): Promise<AssertionResult> {
  try {
    const res = await fetch("http://localhost:3000/api/metrics");
    const data = await res.json();
    const hasTotal = typeof (data?.total_value ?? data?.totalValue ?? data?.sum) === "number";
    const hasCount = typeof (data?.event_count ?? data?.eventCount ?? data?.count) === "number";
    const passed = hasTotal || hasCount;
    return {
      passed,
      message: passed ? "Returns metrics shape." : "Response missing total_value or event_count.",
      details: { hasTotal, hasCount },
    };
  } catch (e) {
    return {
      passed: false,
      message: "API did not respond.",
      details: { error: e instanceof Error ? e.message : String(e) },
    };
  }
}
