import os
from datetime import datetime
from typing import Optional

import clickhouse_connect
import psycopg2
import psycopg2.extras
from fastapi import FastAPI, Query
from fastapi.responses import JSONResponse

app = FastAPI(title="Multi-Dimensional Query Builder")

CLICKHOUSE_HOST = os.environ.get("CLICKHOUSE_HOST", "localhost")
CLICKHOUSE_PORT = int(os.environ.get("CLICKHOUSE_PORT", "8123"))
POSTGRES_URL = os.environ.get("POSTGRES_URL", "postgresql://postgres@localhost:5432/postgres")


def get_ch_client():
    return clickhouse_connect.get_client(
        host=CLICKHOUSE_HOST,
        port=CLICKHOUSE_PORT,
        database="analytics",
    )


def get_pg_conn():
    return psycopg2.connect(POSTGRES_URL)


@app.get("/api/metrics")
def get_metrics(
    region_id: Optional[int] = Query(None),
    product_id: Optional[int] = Query(None),
    start_date: Optional[str] = Query(None),
    end_date: Optional[str] = Query(None),
    group_by: Optional[str] = Query(None),
):
    """Query aggregated metrics with optional dimension filters.

    Query params:
        region_id: filter by region
        product_id: filter by product
        start_date: filter events >= this date (YYYY-MM-DD)
        end_date: filter events <= this date (YYYY-MM-DD)
        group_by: comma-separated list of dimensions to group by (region_id, product_id, date)
    """
    # Build WHERE clause
    conditions = []
    params = {}
    if region_id is not None:
        conditions.append("region_id = {region_id:UInt32}")
        params["region_id"] = region_id
    if product_id is not None:
        conditions.append("product_id = {product_id:UInt32}")
        params["product_id"] = product_id
    if start_date is not None:
        conditions.append("ts >= {start_date:DateTime}")
        params["start_date"] = start_date
    if end_date is not None:
        conditions.append("ts <= {end_date:DateTime}")
        params["end_date"] = end_date

    where = ""
    if conditions:
        where = "WHERE " + " AND ".join(conditions)

    # Build GROUP BY / SELECT
    group_cols = []
    if group_by:
        for g in group_by.split(","):
            g = g.strip()
            if g == "date":
                group_cols.append("toDate(ts) AS date")
            elif g in ("region_id", "product_id"):
                group_cols.append(g)

    if group_cols:
        select_cols = ", ".join(group_cols)
        query = f"SELECT {select_cols}, sum(value) AS total_value, count() AS event_count FROM events {where} GROUP BY {select_cols} ORDER BY {select_cols}"
    else:
        query = f"SELECT sum(value) AS total_value, count() AS event_count FROM events {where}"

    ch = get_ch_client()
    result = ch.query(query, parameters=params)

    if group_cols:
        col_names = [c.name for c in result.column_names] if hasattr(result, 'column_names') else []
        if not col_names:
            col_names = result.column_names if isinstance(result.column_names, list) else list(result.column_names)

        rows = []
        for row in result.result_rows:
            row_dict = {}
            for i, val in enumerate(row):
                key = col_names[i]
                row_dict[key] = str(val) if isinstance(val, (datetime,)) else val
            rows.append(row_dict)

        # Enrich with dimension names from Postgres
        rows = _enrich_dimensions(rows)
        return JSONResponse(content={"rows": rows, "total_value": sum(r.get("total_value", 0) for r in rows), "event_count": sum(r.get("event_count", 0) for r in rows)})
    else:
        row = result.result_rows[0] if result.result_rows else (0, 0)
        return JSONResponse(content={
            "total_value": row[0],
            "event_count": row[1],
        })


def _enrich_dimensions(rows):
    """Join dimension names from Postgres for region_id and product_id."""
    region_ids = {r["region_id"] for r in rows if "region_id" in r}
    product_ids = {r["product_id"] for r in rows if "product_id" in r}

    if not region_ids and not product_ids:
        return rows

    conn = get_pg_conn()
    cur = conn.cursor(cursor_factory=psycopg2.extras.DictCursor)

    region_map = {}
    if region_ids:
        cur.execute("SELECT id, name FROM app.regions WHERE id = ANY(%s)", (list(region_ids),))
        for r in cur.fetchall():
            region_map[r["id"]] = r["name"]

    product_map = {}
    if product_ids:
        cur.execute("SELECT id, name FROM app.products WHERE id = ANY(%s)", (list(product_ids),))
        for r in cur.fetchall():
            product_map[r["id"]] = r["name"]

    conn.close()

    for row in rows:
        if "region_id" in row and row["region_id"] in region_map:
            row["region_name"] = region_map[row["region_id"]]
        if "product_id" in row and row["product_id"] in product_map:
            row["product_name"] = product_map[row["product_id"]]

    return rows


@app.get("/api/dimensions/regions")
def get_regions():
    conn = get_pg_conn()
    cur = conn.cursor(cursor_factory=psycopg2.extras.DictCursor)
    cur.execute("SELECT id, name FROM app.regions ORDER BY id")
    rows = [dict(r) for r in cur.fetchall()]
    conn.close()
    return JSONResponse(content={"regions": rows})


@app.get("/api/dimensions/products")
def get_products():
    conn = get_pg_conn()
    cur = conn.cursor(cursor_factory=psycopg2.extras.DictCursor)
    cur.execute("SELECT id, name FROM app.products ORDER BY id")
    rows = [dict(r) for r in cur.fetchall()]
    conn.close()
    return JSONResponse(content={"products": rows})

